import {manage,resolve,netWorth} from './engine.mjs';
import {financialModel} from './financial-view.mjs';
import {opportunity,surprise} from './events.mjs';
import {RISK_POLICY,canonicalJSON,sha256,policyText} from './risk-rules.mjs';
export function policySignals(s){const m=financialModel(s);return {reserve:m.reserveMonths>=RISK_POLICY.reserveMonths?1:0,coverage:m.after>=0?1:0,installments:m.income>0&&m.installments*10000<=RISK_POLICY.installmentBps*m.income?1:0,model:m};}
export function riskOptions(s){if(!s?.started||s.phase==='finished'||s.route)return [];if(s.phase==='ready')return [{op:'manage',choice:'invest',label:{vi:'Quỹ ML-100',en:'ML-100 fund'}},{op:'manage',choice:'release',label:{vi:'Rút $500 dự phòng',en:'Release $500 reserve'}}];if(s.pending?.type==='opportunity'){const o=opportunity(s.pending.eventId);return [{op:'resolve',choice:'buy',label:{vi:o.vi[0],en:o.en[0]}},{op:'resolve',choice:'skip',label:{vi:'Giữ tiền mặt',en:'Keep cash'}}];}if(s.pending?.type==='expense'&&surprise(s.pending.eventId)?.optional)return [{op:'resolve',choice:'spend',label:{vi:'Chi tiêu tự chọn',en:'Optional purchase'}},{op:'resolve',choice:'skip',label:{vi:'Bỏ qua',en:'Pass'}}];return [];}
export function projectDecision(s,option){if(!riskOptions(s).some(x=>x.op===option?.op&&x.choice===option?.choice))throw Error('RISK_ACTION_INVALID');const clone=structuredClone(s);delete clone.labTrace;Object.defineProperty(clone,'_decisionReplay',{value:true});const accepted=(option.op==='manage'?manage:resolve)(clone,option.choice);if(!accepted)return {option,feasible:false,reason:s.gate.OUT0===0&&['buy','invest'].includes(option.choice)?'STOP':'FUNDS'};const signals=policySignals(clone);return {option,feasible:true,after:clone,signals,forecast:clone.phase!=='finished',netWorth:netWorth(clone),localOutput:signals.reserve&signals.coverage&signals.installments};}
export function decisionInput(state,option){return {schema:'moneylab-decision-input.v1',policy:RISK_POLICY,game:{runId:state.runId,balanceVersion:state.balanceVersion,difficulty:state.difficulty,month:state.month,phase:state.phase,cash:state.cash,reserve:state.reserve,positions:structuredClone(state.positions),gate:structuredClone(state.gate),eventId:state.pending?.eventId||null},action:{op:option.op,choice:option.choice}};}
export async function decisionCommitment(state,option){return sha256(canonicalJSON(decisionInput(state,option)));}
export async function policyCommitment(){return sha256(policyText());}
